# math_utils.py
"""수학 유틸리티 모듈"""

PI = 3.14159

def add(a, b):
    """두 수를 더합니다"""
    return a + b

def multiply(a, b):
    """두 수를 곱합니다"""
    return a * b

class Calculator:
    def __init__(self):
        self.result = 0

    def add(self, value):
        self.result += value
        return self

# 모듈이 직접 실행될 때만 실행
if __name__ == "__main__":
    print("math_utils 모듈이 직접 실행되었습니다")
    print(f"PI = {PI}")

